                    .mapToObj(i -> (java.util.concurrent.Callable<Void>) () -> {
                        start.await();
                        try {
                            raceService.registerRunner(RACE, new RegisterRunnerRequest(
                                    "bib-" + i, 1000L, 1, "req-reg-" + i));
