                "UPDATE penalty_execution "
                        + "SET status = 'CONFIRMED', credited_ms = ?, confirmed_by = ?, confirmed_at = ? "
                        + "WHERE execution_id = ? AND status = 'PENDING'",
                creditedMs, confirmedBy, now, executionId);
    }

